# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: "Split" look: chat with the agent on the left; on the right a
#          workspace holding the data it pulled (tabs of widgets) above a Python
#          console that shares the same variables.
# ---------------------------------------------------------------------------
from __future__ import annotations

import reflex as rx

from . import agent_common as ac
from .common import code_line, switcher


def _ref(name: str, detail: str) -> rx.Component:
    """In chat, a tool result is only a reference; the widget itself lives in the workspace."""
    return rx.el.div(
        ac.handle(name),
        rx.el.span(detail, class_name="dim"),
        rx.el.span("open →", class_name="ref-open"),
        class_name="ref sans",
    )


def _chat() -> rx.Component:
    return rx.el.div(
        rx.el.div("Chat", class_name="pane-title sans"),
        rx.el.div(
            rx.el.div(ac.QUESTION, class_name="bubble is-user sans"),
            rx.el.div(
                ac.tool_steps(),
                _ref("r1", f"framedata · {ac.R1_SHAPE}"),
                rx.el.div(ac.REPLY, class_name="say"),
                class_name="bubble sans",
            ),
            rx.el.div("chart advantage by move", class_name="bubble is-user sans"),
            rx.el.div(_ref("r1", "added a Chart view"), class_name="bubble sans"),
            class_name="chat-scroll",
        ),
        ac.composer("Ask the agent…", ["r1"]),
        class_name="chat-pane",
    )


def _console() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.span(rx.el.span(ac.ICON_PY, class_name="mono accent-green"), " Python console"),
            rx.el.span("same variables the agent fills", class_name="dim"),
            rx.el.span(class_name="spacer"),
            rx.el.span("r1  safe  pl", class_name="mono dim"),
            class_name="console-head sans",
        ),
        rx.el.div(
            *[
                rx.el.div(rx.el.span(">>> ", class_name="dim"), code_line(tokens), class_name="console-line")
                for tokens in ac.PY_LINES
            ],
            rx.el.div(ac.safe_table(), class_name="console-out"),
            rx.el.div(
                rx.el.span(">>> ", class_name="accent-green"),
                rx.el.span(" ", class_name="cursor"),
                class_name="console-line",
            ),
            class_name="console-body mono",
        ),
        class_name="console",
    )


def _workspace() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.span(ac.handle("r1"), " framedata", rx.el.span("×", class_name="dim"), class_name="tab is-active"),
            rx.el.span(ac.handle("safe"), " DataFrame", rx.el.span("×", class_name="dim"), class_name="tab"),
            rx.el.span("+", class_name="tab"),
            class_name="tabbar sans",
        ),
        rx.el.div(ac.r1_widget(height=300, actions=False), class_name="ws-widget"),
        _console(),
        class_name="ws-pane",
    )


def split_page() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.span("reflex-kernel", class_name="title"),
            rx.el.span("little mac on shield", class_name="dim"),
            class_name="titlebar sans",
        ),
        rx.el.div(_chat(), _workspace(), class_name="split-main"),
        switcher("split"),
        class_name="page split",
    )
